// Pega os dados que chegaram no Webhook
const item = $input.first().json;

const errors = [];
const EXPECTED_SECRET = "***REDACTED***";

// 1. Validate query.id (Must exist, not empty, and MUST be an integer)
const idRaw = item.query?.id;
const idNum = Number(idRaw);

if (idRaw === undefined || idRaw === null || String(idRaw).trim() === '') {
  errors.push("Missing or empty required parameter: 'query.id'.");
} else if (isNaN(idNum) || !Number.isInteger(idNum)) {
  errors.push("Invalid parameter: 'query.id' must be a valid integer number (e.g. 123456).");
}

// 2. Validate body.tema
const tema = item.body?.tema;
if (tema === undefined || tema === null || String(tema).trim() === '') {
  errors.push("Missing or empty required parameter: 'body.tema'.");
}

// 3. Validate x-apify-secret
const secretHeader = item.headers ? (item.headers['x-apify-secret'] || item.headers['X-Apify-Secret']) : undefined;

if (!secretHeader || String(secretHeader).trim() === '') {
  errors.push("Missing required header: 'x-apify-secret'.");
} else if (secretHeader !== EXPECTED_SECRET) {
  errors.push("Unauthorized: Invalid 'x-apify-secret' header provided.");
}

// 4. Validate body.webhook_callback
const webhookCallback = item.body?.webhook_callback;
if (webhookCallback === undefined || webhookCallback === null || String(webhookCallback).trim() === '') {
  errors.push("Missing or empty required parameter: 'body.webhook_callback'.");
}

const isValid = errors.length === 0;

// Return JSON error response
return [{
  json: {
    status: isValid ? 200 : 400,
    success: isValid,
    is_valid: isValid,
    error: isValid ? null : "Input Validation Error",
    errors: errors,
    message: isValid ? "Validation successful." : errors.join(" | ")
  }
}];

