parameters.jsCode:
const PERSONAS = [
  { node: 'Persona Fatos Essenciais',   numero: 1, topico: 'Fatos Essenciais' },
  { node: 'Persona Analista Tecnico',   numero: 2, topico: 'Análise Técnica' },
  { node: 'Persona Mercado Consumidor', numero: 3, topico: 'Mercado e Consumidor' },
  { node: 'Persona Verificador Cetico', numero: 4, topico: 'Verificação Cética' },
];
const CAP = 18;

const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
const tokens = s => new Set(norm(s).split(' ').filter(w => w.length > 2));
const jaccard = (a,b) => { const A=tokens(a), B=tokens(b); if(!A.size||!B.size) return 0; const inter=[...A].filter(x=>B.has(x)).length; return inter/(A.size+B.size-inter); };

function extractPerguntas(nodeName) {
  let out;
  try { out = $(nodeName).first().json.output; } catch(e) { return []; }
  if (out === undefined || out === null) return [];
  if (typeof out === 'string') {
    let t = out.replace(/^```(json)?|```$/gm,'').trim();
    const m = t.match(/\{[\s\S]*\}/); if (m) t = m[0];
    try { out = JSON.parse(t); } catch(e) { return []; }
  }
  const arr = out.perguntas || out.questions || [];
  return Array.isArray(arr) ? arr : [];
}

const pesqRaw = $('Lê pesquisa por ID').first().json;
const hook = $('Entrada: nova pesquisa').first().json;
const pesq = { id_pesquisa: pesqRaw.id_pesquisa ?? Number(hook.query.id), webhook_callback: pesqRaw.webhook_callback ?? hook.body.callbackUrl ?? hook.body.webhook_callback };
const seen = [];
const steps = [];
const relatorio = [];
for (const p of PERSONAS) {
  let perguntas = extractPerguntas(p.node);
  perguntas.sort((a,b) => (a.prioridade||3) - (b.prioridade||3));
  let letter = 97; // 'a'
  let usadas = 0;
  for (const q of perguntas) {
    const pergunta = String(q.pergunta || '').trim();
    if (!pergunta) continue;
    if (seen.some(s => jaccard(s, pergunta) > 0.75)) continue;
    seen.push(pergunta);
    steps.push({
      id_pesquisa: pesq.id_pesquisa,
      webhook_callback: pesq.webhook_callback,
      topico_principal: `Step ${p.numero} — ${p.topico}`,
      passo_id: `${p.numero}${String.fromCharCode(letter++)}`,
      descricao_subtopico: pergunta + (q.foco ? ` (Foco: ${q.foco})` : '')
    });
    usadas++;
    if (steps.length >= CAP) break;
  }
  relatorio.push(`${p.node}: ${perguntas.length} geradas, ${usadas} usadas`);
  if (steps.length >= CAP) break;
}
if (steps.length === 0) {
  throw new Error('Nenhuma persona gerou perguntas válidas. Detalhes: ' + relatorio.join(' | '));
}
console.log('Plano consolidado: ' + steps.length + ' passos. ' + relatorio.join(' | '));
return steps.map(s => ({ json: s }));

